function freezeDeep(value){if(value&&typeof value==='object'){Object.values(value).forEach(freezeDeep);Object.freeze(value);}return value;}freezeDeep(modernVisualAssetCatalog);freezeDeep(modernVisualScenePlans);
export function withModernVisuals(original){const plan=modernVisualScenePlans[original.id];if(!plan)return original;const hidden=new Set(plan.hiddenPersonNames);return {...original,actors:plan.mapActors.map(i=>({...i})),props:plan.mapProps.map(i=>({...i})),routes:[...original.routes,...plan.extraRoutes].map(i=>({...i,points:i.points.map(at=>[...at])})),tags:original.tags.filter(t=>!(t.kind==='person'&&hidden.has(t.text))).map(t=>({...t})),namesOutsideMap:[...new Set((plan.illustration?.groups??[]).flatMap(g=>g.figures).filter(i=>i.kind==='person').map(i=>i.name))],textOnlyPeople:plan.textOnlyPeople.map(i=>({...i})),excludedPersonNames:plan.excludedPersonNames.map(i=>({...i})),personAliases:plan.personAliases.map(i=>({...i})),duration:original.duration||2600};}
export function modernIllustrationFor(sceneOrId){return modernVisualScenePlans[typeof sceneOrId==='string'?sceneOrId:sceneOrId?.id]?.illustration||null;}
export const modernVisualEdition=Object.fromEntries(Object.entries(modernEdition).map(([id,scenes])=>[id,scenes.map(withModernVisuals)]));
